names = repo.list("src")
out = {}
for n in names:
    if n.endswith("/"):
        for m in repo.list("src/" + n):
            out["src/" + n + m] = repo.read("src/" + n + m)
    else:
        out["src/" + n] = repo.read("src/" + n)
out["Cargo.toml"] = repo.read("Cargo.toml")
return out

